func TestOptions(t *testing.T) {
	testCases := []struct {
		setAsDefault           bool
		nvidiaRuntimeName      string
		expectedDefaultRuntime string
		expectedRuntimes       Runtimes
	}{
		{
			expectedRuntimes: Runtimes{
				"nvidia": Runtime{
					name: "nvidia",
					Path: "/usr/bin/nvidia-container-runtime",
				},
				"nvidia-cdi": Runtime{
					name: "nvidia-cdi",
					Path: "/usr/bin/nvidia-container-runtime.cdi",
				},
				"nvidia-legacy": Runtime{
					name: "nvidia-legacy",
					Path: "/usr/bin/nvidia-container-runtime.legacy",
				},
			},
		},
		{
			setAsDefault:           true,
			expectedDefaultRuntime: "nvidia",
			expectedRuntimes: Runtimes{
				"nvidia": Runtime{
					name:         "nvidia",
					Path:         "/usr/bin/nvidia-container-runtime",
					SetAsDefault: true,
				},
				"nvidia-cdi": Runtime{
					name: "nvidia-cdi",
					Path: "/usr/bin/nvidia-container-runtime.cdi",
				},
				"nvidia-legacy": Runtime{
					name: "nvidia-legacy",
					Path: "/usr/bin/nvidia-container-runtime.legacy",
				},
			},
		},
		{
			setAsDefault:           true,
			nvidiaRuntimeName:      "nvidia",
			expectedDefaultRuntime: "nvidia",
			expectedRuntimes: Runtimes{
				"nvidia": Runtime{
					name:         "nvidia",
					Path:         "/usr/bin/nvidia-container-runtime",
					SetAsDefault: true,
				},
				"nvidia-cdi": Runtime{
					name: "nvidia-cdi",
					Path: "/usr/bin/nvidia-container-runtime.cdi",
				},
				"nvidia-legacy": Runtime{
					name: "nvidia-legacy",
					Path: "/usr/bin/nvidia-container-runtime.legacy",
				},
			},
		},
		{
			setAsDefault:           true,
			nvidiaRuntimeName:      "NAME",
			expectedDefaultRuntime: "NAME",
			expectedRuntimes: Runtimes{
				"NAME": Runtime{
					name:         "NAME",
					Path:         "/usr/bin/nvidia-container-runtime",
					SetAsDefault: true,
				},
				"nvidia-cdi": Runtime{
					name: "nvidia-cdi",
					Path: "/usr/bin/nvidia-container-runtime.cdi",
				},
				"nvidia-legacy": Runtime{
					name: "nvidia-legacy",
					Path: "/usr/bin/nvidia-container-runtime.legacy",
				},
			},
		},
		{
			setAsDefault:      false,
			nvidiaRuntimeName: "NAME",
			expectedRuntimes: Runtimes{
				"NAME": Runtime{
					name: "NAME",
					Path: "/usr/bin/nvidia-container-runtime",
				},
				"nvidia-cdi": Runtime{
					name: "nvidia-cdi",
					Path: "/usr/bin/nvidia-container-runtime.cdi",
				},
				"nvidia-legacy": Runtime{
					name: "nvidia-legacy",
					Path: "/usr/bin/nvidia-container-runtime.legacy",
				},
			},
		},
	}

	for i, tc := range testCases {
		t.Run(fmt.Sprintf("%d", i), func(t *testing.T) {
			runtimes := GetRuntimes(
				WithNvidiaRuntimeName(tc.nvidiaRuntimeName),
				WithSetAsDefault(tc.setAsDefault),
				WithRoot("/usr/bin"),
			)

			require.EqualValues(t, tc.expectedRuntimes, runtimes)
			require.Equal(t, tc.expectedDefaultRuntime, runtimes.DefaultRuntimeName())
		})
	}
}

