package installer

import (
	"bytes"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestWrapperRender(t *testing.T) {
	testCases := []struct {
		description string
		w           *wrapper
		expected    string
	}{
		{
			description: "executable is added",
			w: &wrapper{
				WrappedExecutable:            "some-runtime",
				DefaultRuntimeExecutablePath: "runc",
			},
			expected: `#! /bin/sh
	/dest-dir/some-runtime \
		"$@"
`,
		},
		{
			description: "module check is added",
			w: &wrapper{
				WrappedExecutable:            "some-runtime",
				CheckModules:                 true,
				DefaultRuntimeExecutablePath: "runc",
			},
			expected: `#! /bin/sh
cat /proc/modules | grep -e "^nvidia " >/dev/null 2>&1
if [ "${?}" != "0" ]; then
	echo "nvidia driver modules are not yet loaded, invoking runc directly" >&2
	exec runc "$@"
fi
	/dest-dir/some-runtime \
		"$@"
`,
		},
		{
			description: "environment is added",
			w: &wrapper{
				WrappedExecutable: "some-runtime",
				Envvars: map[string]string{
					"PATH": "/foo/bar/baz",
				},
				DefaultRuntimeExecutablePath: "runc",
			},
			expected: `#! /bin/sh
PATH=/foo/bar/baz \
	/dest-dir/some-runtime \
		"$@"
`,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.description, func(t *testing.T) {
			r := render{
				wrapper: tc.w,
				DestDir: "/dest-dir",
			}
			reader, err := r.render()
			require.NoError(t, err)

			var content bytes.Buffer
			_, err = content.ReadFrom(reader)
			require.NoError(t, err)

			require.Equal(t, tc.expected, content.String())
		})
	}
}

