`,
			},
			// nvidia-cdi-hook is installed unwrapped, so no wrapper content is rendered
			// for it (it does not appear in contentCalls).
			{
				path: "/foo/bar/baz/nvidia-container-cli",
				mode: 0o777,
				wrapper: `#! /bin/sh
